INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2659, 'koKR', 'Gdy zaglądasz w Oko, twój umysł wypełniają obrazy wielkiej bitwy...$b$bTen straszliwy konflikt toczy się chyba gdzieś w Lordaeronie...$b$bLedwie dostrzegasz samotną kobiecą postać, która stoi pośród tysiąca trupów i odpiera morze Plagi...$b$bJest w beznadziejnej przewadze wroga...$b$bZ jej dłoni wystrzelają smugi światła, przecinając nieumarłych setkami.', 0),
(2666, 'koKR', 'Wszystko na próżno, jak się zdaje...$b$bChwilę później kapłankę zalewają zwłoki wieśniaków, którzy ją otaczali...$b$bPolegli powstali.', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(7865, 'koKR', '%s nie chce zginąć, gdy jego pan jest w niebezpieczeństwie!', '', 0),
(7866, 'koKR', '%s pada i zaczyna się tlić.', '', 0),
(7867, 'koKR', '%s znów zapala się od żaru innego Ognistego ogara!', '', 0),
(8253, 'koKR', '%s oddaje ostatnią przysługę Ragnarosowi...', '', 0),
(8254, 'koKR', '%s zmusza jednego ze swoich Zaprzysiężonych ogniowi do erupcji!', '', 0);
